UPDATE documents
SET status = #{status}, error_message = #{errorMessage}
WHERE id = #{id}

UPDATE documents
SET status = #{status}, error_message = #{errorMessage}
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE documents
SET parent_count = #{parentCount},
    child_count = #{childCount}
WHERE id = #{id}

UPDATE documents
SET updated_at = NOW()
WHERE id = #{id}
  AND status = #{status}
